import { build } from 'esbuild';
import { readFile, writeFile } from 'node:fs/promises';
import assert from 'node:assert/strict';

const result = await build({
  entryPoints: [new URL('app.jsx', import.meta.url).pathname],
  bundle: true,
  write: false,
  minify: true,
  jsx: 'automatic',
  target: ['es2020'],
  define: { 'process.env.NODE_ENV': '"production"' },
  legalComments: 'inline',
});
const css = await readFile(new URL('style.css', import.meta.url), 'utf8');
const script = result.outputFiles[0].text.replace(/<\/script/gi, '<\\/script');
const html = `<!doctype html>
<!-- Generated by prysm/control-ui/build.mjs. Edit the React source, then run npm run build. -->
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <meta name="theme-color" content="#f7f7fb">
  <title>Prysm · Light control</title>
  <style>${css}</style>
</head>
<body>
  <div id="root"><p class="loading">Connecting to your lights…</p></div>
  <noscript>Enable JavaScript to control your lights.</noscript>
  <script>${script}</script>
</body>
</html>
`;
const output = new URL('../src/control.html', import.meta.url);
if (process.argv.includes('--check')) {
  assert.equal(await readFile(output, 'utf8'), html, 'Rebuild control.html with npm run build');
} else {
  await writeFile(output, html);
}
